// Parse and normalize Calendly webhook payload (invitee.created / invitee.canceled)
const body = $input.item.json.body || $input.item.json;
const event = body.event || 'invitee.created';
const payload = body.payload || body;

const clientName = payload.name || payload.first_name ? `${payload.first_name || ''} ${payload.last_name || ''}`.trim() : 'Valued Client';
const clientEmail = payload.email || 'N/A';
const questions = payload.questions_and_answers || [];

// Extract phone and custom answers
let clientPhone = payload.text_reminder_number || 'N/A';
let requestedService = 'Custom Nail Art / Gel Session';

for (const q of questions) {
  const questionText = (q.question || '').toLowerCase();
  if (questionText.includes('phone') || questionText.includes('teléfono') || questionText.includes('whatsapp')) {
    clientPhone = q.answer || clientPhone;
  }
  if (questionText.includes('service') || questionText.includes('servicio') || questionText.includes('diseño')) {
    requestedService = q.answer || requestedService;
  }
}

const rawStartTime = payload.scheduled_event ? payload.scheduled_event.start_time : payload.event_start_time || new Date().toISOString();
const eventStartTime = new Date(rawStartTime).toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'full', timeStyle: 'short' });

return {
  json: {
    eventType: event,
    isCreated: event === 'invitee.created',
    isCanceled: event === 'invitee.canceled',
    clientName: clientName,
    clientEmail: clientEmail,
    clientPhone: clientPhone,
    clientPhoneClean: clientPhone.replace(/[^0-9]/g, ''),
    serviceName: requestedService,
    eventStartTime: eventStartTime,
    rawStartTime: rawStartTime,
    depositRequired: 35,
    studioAddress: 'Bay Ridge, Brooklyn, NY 11209 (Private Studio Atelier)',
    studioRules: '15 min grace period; 24h advance notice for cancellations.',
    instagramOfficial: '@iva_nailart_nyc'
  }
};

